# Section 5 speech and accent lock, Section 6 regions.
def S(k, name, region, talk, never, page, quotes, pressure, open_=""):
    return dict(k=k, name=name, region=region, talk=talk, never=never, page=page, quotes=quotes, pressure=pressure, open=open_)

